struct DecodedPpcInstruction {
  PpcOpcode opcode = PpcOpcode::kUnknown;
  uint32_t raw = 0;
  uint8_t rt = 0;
  uint8_t ra = 0;
  uint8_t bo = 0;
  uint8_t bi = 0;
  uint8_t rb = 0;
  uint8_t rc = 0;
  uint8_t cr_field = 0;
  uint8_t shift = 0;
  uint8_t mask_begin = 0;
  uint8_t mask_end = 0;
  uint16_t spr = 0;
  int32_t immediate = 0;
  bool is_64_bit = false;
  bool absolute = false;
  bool link = false;
  bool record = false;
};

DecodedPpcInstruction DecodePpcInstruction(uint32_t raw);

